-- ============================================-- 审批流程V2问题修复-- ============================================-- 1. 修复审批节点数据（清理旧数据，重新插入）DELETE FROM approval_history;DELETE FROM approval_record;DELETE FROM approval_node WHERE id IN (1, 2, 3, 4);-- 重新插入带dept_id的审批节点-- 技术部入职审批：技术部经理(dept_id=2) → HR(null)-- 市场部入职审批：市场部经理(dept_id=3) → HR(null)INSERT INTO approval_node (id, process_id, node_name, role_id, role_code, dept_id, node_order, status, create_time) VALUES(1, 1, '技术部经理审批', 3, 'dept_manager', 2, 1, 1, NOW()),(2, 1, 'HR审批', 1, 'admin', NULL, 2, 1, NOW()),(3, 1, '市场部经理审批', 3, 'dept_manager', 3, 1, 1, NOW()),(4, 1, 'HR审批(市场部)', 1, 'admin', NULL, 2, 1, NOW());-- 2. 修复部门经理管辖关系UPDATE sys_user SET managed_dept_id = NULL WHERE id IN (1, 2, 4, 6, 7);  -- admin、张三、王五、孙七、员工C没有管辖UPDATE sys_user SET managed_dept_id = 2 WHERE id = 3;  -- 李四管技术部UPDATE sys_user SET managed_dept_id = 3 WHERE id = 5;  -- 赵六管市场部-- 3. 验证数据SELECT '=== 部门经理配置 ===' AS info;SELECT id, username, real_name, role_code, managed_dept_id FROM sys_user WHERE managed_dept_id IS NOT NULL;SELECT '=== 审批节点配置 ===' AS info;SELECT n.id, n.node_name, n.role_code, n.dept_id, d.name AS dept_name, n.node_orderFROM approval_node nLEFT JOIN department d ON n.dept_id = d.idORDER BY n.process_id, n.dept_id, n.node_order;
